select n.nspname,c.relname,r.name client_role,p.name forbidden_right
from pg_class c join pg_namespace n on n.oid=c.relnamespace
cross join(values('anon'),('authenticated'))r(name)
cross join(values('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN'))p(name)
where n.nspname='public' and c.relkind in('r','p') and has_table_privilege(r.name,c.oid,p.name)
order by 1,2,3,4;

select n.nspname,c.relname,c.relrowsecurity,c.relforcerowsecurity
from pg_class c join pg_namespace n on n.oid=c.relnamespace
where n.nspname in('public','private') and c.relkind in('r','p') order by 1,2;

select pg_get_userbyid(d.defaclrole) creator,n.nspname,d.defaclobjtype,d.defaclacl::text
from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace
order by 1,2,3;

select n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args,
pg_get_userbyid(p.proowner) owner,p.proconfig,
has_function_privilege('anon',p.oid,'EXECUTE') anon_execute,
has_function_privilege('authenticated',p.oid,'EXECUTE') authenticated_execute
from pg_proc p join pg_namespace n on n.oid=p.pronamespace
where n.nspname in('public','private') and p.prosecdef order by 1,2,3;

